  if(s.room==='club'){this.sign('THE VELVET ROPE',210,32,color);this.rect(238,51,93,125,'#352845',5);this.rect(248,62,72,108,'#171a2b',3);this.line(284,62,284,170,'#6e547e',2);this.rect(36,63,72,102,'#ad91b1',9);this.rect(42,69,60,90,'#485169',5);this.line(48,127,96,83,'#b6c6d24a',8);this.npc(204,131,'#51446d','brick');this.line(145,170,361,170,'#d07da6',5);for(const x of [142,364]){this.circle(x,160,6,'#dfbb79');this.rect(x-3,163,6,39,'#bca16f');}}
